/* Rotation stays in output pixels, including hit-testing, groups and exports. */
'use strict';
globalThis.SplitRotation=(()=>{
 const normal=angle=>((angle+180)%360+360)%360-180;
 const valid=()=>selectedLayers().length&&!selectedLayers().some(l=>l.locked||l.hidden);
 const priorProperties=renderProperties,priorSelection=renderSelection,priorMove=stageMove;
 function update(){const layers=selectedLayers(),editable=valid();$('rotationControls').hidden=!editable;if(editable){const angles=layers.map(l=>normal(l.rotation||0)),same=angles.every(a=>Math.abs(a-angles[0])<.0001);$('layerRotation').value=same?Math.round(angles[0]*10)/10:'';$('layerRotation').placeholder=same?'0':'Vários';}const l=selected();$('buttonCorners').hidden=!editable||layers.length!==1||l.type!=='cta';if(l?.type==='cta'){const radius=l.cornerRadius??9;$('roundedButton').checked=radius>0;$('buttonRadiusField').hidden=radius<=0;$('buttonRadius').value=radius||15;$('buttonRadiusValue').textContent=`${radius||15}%`;}}
 renderProperties=function(){priorProperties();update();};
 function transform(originals,center,delta){const f=current(),a=delta*Math.PI/180,c=Math.cos(a),s=Math.sin(a);for(const old of originals){const l=f.layers.find(l=>l.id===old.id);if(!l)continue;const dx=(old.x+old.w/2)*f.w-center.x,dy=(old.y+old.h/2)*f.h-center.y;l.x=(center.x+dx*c-dy*s)/f.w-old.w/2;l.y=(center.y+dx*s+dy*c)/f.h-old.h/2;l.rotation=normal((old.rotation||0)+delta);l.manualLayout=true;}}
 function centerOf(layers){const b=selectionBounds(layers),f=current();return{x:(b.x+b.w/2)*f.w,y:(b.y+b.h/2)*f.h};}
 function setAngle(value){if(!valid()||!Number.isFinite(value)||value<-180||value>180)return false;SplitEditor.finishInteraction();const originals=selectedLayers().map(l=>({...l})),first=originals[0].rotation||0,same=originals.every(l=>Math.abs((l.rotation||0)-first)<.0001),delta=normal(value-(same?first:0));if(Math.abs(delta)<.0001)return false;checkpoint();transform(originals,centerOf(originals),delta);alignmentGuides=[];renderEditor();renderCards();return true;}
 function reset(){if(!valid())return;const layers=selectedLayers();if(layers.every(l=>!(l.rotation||0)))return;const first=layers[0].rotation||0;if(layers.every(l=>(l.rotation||0)===first)){setAngle(0);return;}SplitEditor.finishInteraction();checkpoint();for(const l of layers){l.rotation=0;l.manualLayout=true;}renderEditor();renderCards();}
 function start(ev){if(ev.button!==0||!valid()||drag||pan||spacePressed)return;ev.preventDefault();ev.stopPropagation?.();const originals=selectedLayers().map(l=>({...l})),center=centerOf(originals),p=coords(ev,$('stage'),true),f=current();drag={type:'rotation',originals,center,startAngle:Math.atan2(p.y*f.h-center.y,p.x*f.w-center.x),pointerId:ev.pointerId,changed:false};$('stage').setPointerCapture(ev.pointerId);$('stage').focus?.();}
 stageMove=function(ev){if(drag?.type!=='rotation'){priorMove(ev);return;}if(ev.pointerId!==drag.pointerId)return;const f=current(),p=coords(ev,$('stage'),true);let delta=normal((Math.atan2(p.y*f.h-drag.center.y,p.x*f.w-drag.center.x)-drag.startAngle)*180/Math.PI);if(ev.shiftKey)delta=Math.round(delta/15)*15;if(!drag.changed&&Math.abs(delta)<.2)return;if(!drag.changed){checkpoint();drag.changed=true;}transform(drag.originals,drag.center,delta);alignmentGuides=[];render($('stage'),f,true,4096);renderProperties();globalThis.SplitProjects?.changed();};
 renderSelection=function(f){priorSelection(f);const overlay=$('selectionOverlay');if(overlay.hidden)return;let handle=overlay.querySelector('.layer-rotate');if(!handle){handle=document.createElement('button');handle.type='button';handle.className='layer-rotate';handle.setAttribute('aria-label','Girar seleção');handle.title='Arraste para girar · Shift: intervalos de 15°';handle.onpointerdown=start;overlay.append(handle);}handle.classList.toggle('rotating',drag?.type==='rotation');};
 function corners(value){const l=selected();if(!valid()||selectedLayers().length!==1||l?.type!=='cta'||!Number.isFinite(value))return;SplitEditor.finishInteraction();const radius=clamp(value,0,50);if((l.cornerRadius??9)===radius)return;checkpoint();l.cornerRadius=radius;l.manualLayout=true;renderEditor();renderCards();}
 $('layerRotation').onchange=ev=>{if(!setAngle(Number(ev.target.value)))update();};$('resetRotation').onclick=reset;$('roundedButton').onchange=ev=>corners(ev.target.checked?15:0);$('buttonRadius').onchange=ev=>corners(Number(ev.target.value));$('buttonRadius').oninput=ev=>$('buttonRadiusValue').textContent=`${ev.target.value}%`;
 $('stage').onpointermove=stageMove;update();
 return{setAngle,reset,start,transform,normal,corners};
})();
